// ── PolicyQuestion (11 rows)
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('68496f9b-4331-4e85-a91d-7194c412ebad', 'What should you do if you receive an email asking you to verify your banking credentials by clicking a link?', 'Legitimate banks and IT teams never ask for credentials via email. Always report such emails to the IT Security team and delete them without clicking any links.', TRUE, 0, '2026-06-28 11:47:10.968', '2026-06-28 11:47:10.968') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('62821d35-21e3-4482-9f26-817998d84024', 'According to Nisir Bank''s Information Security Policy, how often must employees change their system passwords?', 'The ISP mandates password rotation every 90 days. Passwords must be at least 8 characters, combining letters, numbers, and symbols, and must not be reused for at least 5 cycles.', TRUE, 1, '2026-06-28 11:47:11.013', '2026-06-28 11:47:11.013') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('aa6df096-7511-4528-a508-587961752050', 'Which of the following is the SAFEST way to handle confidential customer data when working remotely?', 'Confidential customer data must only be accessed through the bank''s approved VPN on bank-issued devices. Personal devices and public Wi-Fi networks are explicitly prohibited under the Remote Access Policy.', TRUE, 2, '2026-06-28 11:47:11.015', '2026-06-28 11:47:11.015') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('6b5cb5e1-a894-4293-ad3b-e951be72b823', 'An employee finds a USB flash drive in the parking lot with a Nisir Bank logo on it. What is the correct action?', 'Unknown USB devices could contain malware designed to auto-execute when plugged in (a ''baiting'' attack). The correct action is to hand it to IT Security without connecting it to any device.', TRUE, 3, '2026-06-28 11:47:11.017', '2026-06-28 11:47:11.017') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('2fa61105-6a7e-48eb-acfa-12e3043a424d', 'What is the minimum classification level that requires documents to be encrypted before being emailed outside the bank?', 'Under the Data Classification Policy, any document classified as ''Confidential'' or above must be encrypted before transmission outside the bank. ''Internal Use'' documents may be emailed internally but not externally without encryption.', TRUE, 4, '2026-06-28 11:47:11.021', '2026-06-28 11:47:11.021') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('c35c610e-98f3-4f2a-b2ac-5cf6462fdcc5', 'You notice a colleague has left their workstation unlocked and unattended. What should you do?', 'Per the Clean Desk and Screen Lock Policy, workstations must be locked whenever unattended. The correct response is to lock the screen on their behalf and remind them of the policy — not to access their account.', TRUE, 5, '2026-06-28 11:47:11.023', '2026-06-28 11:47:11.023') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('1879bd58-a4e2-47c0-874f-cea8948f81b2', 'Which of the following passwords meets Nisir Bank''s password complexity requirements?', 'The ISP requires passwords to be at least 8 characters and include uppercase letters, lowercase letters, numbers, and special characters. ''Nb@2026Sec!'' meets all criteria.', TRUE, 6, '2026-06-28 11:47:11.025', '2026-06-28 11:47:11.025') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('2b6a5bec-b777-4e23-9160-2df921e39382', 'How long does Nisir Bank''s policy require that security incident logs be retained?', 'The Incident Management Policy requires that all security incident records be retained for a minimum of 5 years to support forensic investigations, regulatory audits, and compliance requirements.', TRUE, 7, '2026-06-28 11:47:11.027', '2026-06-28 11:47:11.027') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('983561b6-0fc4-45fb-9bcf-327bc68fc997', 'A customer calls and urgently requests that you reset their PIN over the phone. You cannot reach the branch manager. What should you do?', 'Customer identity must be verified through approved in-person or digital channels before any account changes are made. Phone-based PIN resets without proper verification violate the Customer Authentication Policy and could enable social engineering attacks.', TRUE, 8, '2026-06-28 11:47:11.029', '2026-06-28 11:47:11.029') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('00bca7e5-211f-493b-9853-c6b4d853178a', 'Which of the following is NOT an acceptable use of Nisir Bank''s IT resources according to the Acceptable Use Policy?', 'Bank IT resources are provided for official business use. Cryptocurrency mining, streaming entertainment, and operating personal businesses are all prohibited uses listed in the AUP. Accessing the internal knowledge base for customer queries is an approved activity.', TRUE, 9, '2026-06-28 11:47:11.031', '2026-06-28 11:47:11.031') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "PolicyQuestion" ("id", "question", "explanation", "isActive", "order", "createdAt", "updatedAt") VALUES ('cmqy01xq3000k5oi6809v1xgc', 'what is x?', 'It is a letter becase it is', TRUE, 10, '2026-06-28 13:24:51.195', '2026-06-28 13:24:51.195') ON CONFLICT DO NOTHING`);
