await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('8941080f-3e1d-44b8-8e73-2f8e7360ed20', 'f8bb1265-e7a4-4d1e-91e9-4118608a14bd', 'EMP-003', 'Employee 003', 'I asked IT about a password manager last quarter. They said KeePass is approved for offline use on bank devices. You keep one master password and it generates/stores all the others. Might be worth requesting formal guidance from IT Security.', '2026-06-27 20:59:31.300') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('9e59dfa5-d663-4117-80c9-f1aabb230e0b', 'ccff5939-f7ee-4d5d-aa35-5cd89c790c15', 'EMP-082', 'Employee 082', 'This is almost certainly a phishing simulation or a real phishing attempt. The 24-hour urgency is a classic social engineering tactic. Always verify with IT directly by calling Ext. 4000 — never through a link in the email itself.', '2026-06-27 21:05:43.343') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('904ef7fc-a8ba-4fc0-af42-fee549c681e0', '30178764-62f1-43f3-a03e-50bb5717b2c6', 'EMP-015', 'Employee 015', 'Reporting speed matters a lot. The SOC told me that within the first 15–30 minutes they can usually contain a potential compromise before credentials are harvested or malware executes. The longer you wait, the worse it can get. Call immediately — they will not judge you for making a mistake.', '2026-06-27 21:11:45.365') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('036eef82-494d-4e1f-85d4-af8572fbf6e6', '30178764-62f1-43f3-a03e-50bb5717b2c6', 'EMP-023', 'Employee 023', 'One extra point: if you entered any credentials on the suspicious page before realising, tell the SOC that immediately. They''ll need to trigger a password reset across affected systems as a priority. Disclosing this quickly makes a huge difference to the response outcome.', '2026-06-27 21:14:15.312') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('a0c7998b-e44f-4147-957f-0fbc96bf4fd4', 'f8bb1265-e7a4-4d1e-91e9-4118608a14bd', 'EMP-015', 'Employee 015', 'The IT Security team recommends using a passphrase approach — three or four unrelated words joined together (e.g., ''coffee-lamp-river-22''). They''re long enough to be secure but easier to remember than random characters.', '2026-06-27 21:27:46.983') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('a4e1ccc3-fc01-4df6-aa66-c36ea2ab7767', '3a1f5b09-0e06-4231-972b-7bd912b52866', 'EMP-047', 'Employee 047', 'Great list. I''d add: check if the attachment type makes sense. A PDF from HR is normal; an .exe file or a password-protected zip from an unknown sender is not. Unexpected attachments with password protection are a major red flag.', '2026-06-27 21:28:12.006') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('c4907703-f964-4a3f-9363-33eda390f7ea', '8eb2e68a-a30a-4c25-9ec3-d1ab436a04e0', 'EMP-038', 'Employee 038', 'Same rule applies to national ID numbers and phone numbers — partial masking is the minimum standard. The full NBE directive is in the Resources section of this portal. Recommend all staff in customer-facing roles read section 4 carefully.', '2026-06-27 21:29:50.565') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('8056cf3b-0003-4431-b30f-c641008bd7cc', '8eb2e68a-a30a-4c25-9ec3-d1ab436a04e0', 'EMP-082', 'Employee 082', 'Great question. Masked account numbers (last 4 digits only) are generally acceptable in internal email for operational purposes. Full account numbers should always go through the secure document system or be communicated verbally. If in doubt, contact the Compliance team on Ext. 4200 for a written confirmation.', '2026-06-27 21:31:48.701') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('bcd55396-db6f-4cab-9b4c-1bf8a7047a7c', '3a1f5b09-0e06-4231-972b-7bd912b52866', 'EMP-038', 'Employee 038', 'This should be pinned for everyone to see. One thing I''d emphasize: when in doubt, NEVER click. Just pick up the phone and verify directly with the sender. A few seconds of verification can prevent hours of incident response work.', '2026-06-27 21:34:05.351') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('54be5344-8697-4e67-9c22-7417d1397c77', 'f8bb1265-e7a4-4d1e-91e9-4118608a14bd', 'EMP-061', 'Employee 061', 'Whatever method you use, please never write passwords on sticky notes near your workstation! I''ve seen this happen and it''s a serious audit finding. The passphrase tip from above is genuinely useful.', '2026-06-27 21:34:38.854') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('129a289a-4f49-40eb-81b5-5022a8a73089', 'ccff5939-f7ee-4d5d-aa35-5cd89c790c15', 'EMP-047', 'Employee 047', 'Good instinct not to click! A few red flags you spotted correctly: the domain is ''nisir-maintenance.et'', not our official nisirbank.et domain. Legitimate IT will never ask for credentials via email. Report it to security@nisirbank.et.', '2026-06-27 21:44:59.998') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('7a82f20b-4009-43c6-8c03-3444692dd866', '3a1f5b09-0e06-4231-972b-7bd912b52866', 'EMP-003', 'Employee 003', 'Number 4 is the most important one for me. I''ve started hovering over every link before clicking — even from people I know, since their account could be compromised. It takes two extra seconds and has already saved me from one suspicious link.', '2026-06-27 21:45:46.315') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('50201297-1232-461a-b8ae-1bab7f385f12', '3a1f5b09-0e06-4231-972b-7bd912b52866', 'EMP-023', 'Employee 023', 'I also check whether my name appears in the greeting. Phishing emails often use generic greetings like ''Dear Staff Member'' or ''Dear Customer''. Real internal comms usually address you by name.', '2026-06-27 21:52:28.049') ON CONFLICT DO NOTHING`);
await run(`INSERT INTO "DiscussionReply" ("id", "discussionId", "employeeId", "authorName", "body", "createdAt") VALUES ('8bf8e2ce-e308-42cd-9cd4-9904bad1b3ee', '30178764-62f1-43f3-a03e-50bb5717b2c6', 'EMP-047', 'Employee 047', 'The official steps are: (1) Stop using the device immediately — don''t try to close the browser or ''fix'' anything yourself. (2) Call the Security Operations Centre on Ext. 4444 — they operate 24/7. (3) Do NOT power off the device unless instructed — the SOC may need to capture forensic evidence. (4) Fill in an incident report form afterward (available on the IT intranet).', '2026-06-27 21:58:49.379') ON CONFLICT DO NOTHING`);
